command:
await foundry.applications.api.DialogV2.wait({
	window: { title: "Play a Sound" },
	content: `
		<div style="display:flex; flex-direction:column; gap:8px;">
			<label>Sound File:</label>
			<div style="display:flex; gap:6px;">
				<input type="text" name="soundPath" value="assets/Sounds/" style="flex:1;" />
				<button type="button" name="browse">Browse</button>
			</div>
		</div>
	`,
	buttons: [
		{
			action: "play",
			label: "Play Sound",
			default: true,
			callback: (event, button, dialog) => {
				const path = button.form.elements.soundPath.value;
				if (!path) return;

				foundry.audio.AudioHelper.play(
					{ src: path, volume: 0.5, autoplay: true, loop: false },
					true
				);
			}
		}
	],
	rejectClose: false,
	render: (event, dialog) => {
		const html = dialog.element;
		const input = html.querySelector('input[name="soundPath"]');
		const browseBtn = html.querySelector('button[name="browse"]');

		browseBtn.addEventListener("click", () => {
			const FP = foundry.applications.apps.FilePicker.implementation;
			new FP({
				type: "audio",
				current: input.value || "assets/Sounds/",
				callback: (path) => { input.value = path; }
			}).render(true);
		});
	}
});
